<script setup lang="tsx">
// AI 教练：我的会话列表（设计文档 §8「会话历史界面」）
//
// 数据：GET /ai/conversation/list —— 后端按 modify_time 倒序做游标分页，
// 返回 AiConversationPageView{ list, has_more, next_cursor_time, next_cursor_id }
// （见 DidaOJ-go/web/controller/ai.go 与 foundation-service/ai_chat.go），
// 因此这里用「加载更多」逐页追加，不做全量拉取（会话可能很多）。
//
// 布局：桌面端沿用项目列表页的 t-table；移动端用原生 div 卡片
// （tdesign 没有 Cell / SwipeCell，按项目约定手写，断点复用 useBreakpoint，业务逻辑只写一份）。

import { computed, onMounted, ref } from "vue";
import { useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess, ShowTextTipsWarn } from "@/util/tips";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { ResolveAiErrorText, useAiCoachStore } from "@/stores/aiCoach.ts";
import { GetAiConversationList, PostAiConversationDelete, PostAiConversationRename } from "@/apis/ai-conversation.ts";
import {
  CanOpenConversationRef,
  GetConversationRefHint,
  GetConversationRefLabel,
  GetConversationSceneTitle,
  GetConversationTimeText,
  GetConversationTitle,
  OpenConversationRef,
} from "@/views/ai/ai-conversation-display.ts";
import type { AiConversationItem, AiConversationPage } from "@/apis/ai-conversation.ts";
import type { CellParams, TableColumn } from "@/types/table";
import type { TableRowData } from "tdesign-vue-next";

const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();
// 复用浮窗的 store：继续对话要把会话载入全局浮窗（App.vue 全局挂载），场景名也与浮窗共用一份缓存
const store = useAiCoachStore();

/** 每页条数：与后端 aiChatConversationDefaultLimit 一致（后端还有上限，由后端收敛） */
const PAGE_SIZE = 20;

const items = ref<AiConversationItem[]>([]);
/** 首屏 / 重试 / 刷新 */
const loading = ref(false);
/** 加载更多（与首屏区分，避免整页 loading 遮住已有内容） */
const loadingMore = ref(false);
/** 是否已完成过一次加载：区分「还没加载」与「确实没有会话」 */
const loaded = ref(false);
const hasMore = ref(false);
const errorCode = ref(0);
const errorMessage = ref("");

// 下一页游标：由后端在 has_more 时回传，缺失即代表没有下一页
let cursorTime = "";
let cursorId = 0;

function handleOpenDetail(id: number) {
  void router.push({ name: "ai-conversation-detail", params: { id: String(id) } });
}

/** 继续对话：打开全局浮窗并载入该会话（浮窗由 App.vue 全局挂载，这里不渲染任何浮窗） */
async function handleContinue(item: AiConversationItem) {
  if (store.generating) {
    ShowTextTipsWarn(globalProperties, "AI 正在生成中，请先停止或等本轮结束后再切换会话");
    return;
  }
  await store.open();
  await store.loadConversation(item.id);
}

// ── 游标分页 ──

/** 应用后端回传的下一页游标：只有 has_more 且带回 cursor_time 才算还有下一页 */
function applyCursor(page: AiConversationPage | undefined) {
  cursorTime = page?.next_cursor_time ?? "";
  cursorId = page?.next_cursor_id ?? 0;
  hasMore.value = page?.has_more === true && !!cursorTime;
}

/** 重置列表状态（首屏加载与重试共用） */
async function loadFirstPage() {
  loading.value = true;
  errorCode.value = 0;
  errorMessage.value = "";
  hasMore.value = false;
  cursorTime = "";
  cursorId = 0;
  try {
    const res = await GetAiConversationList({ limit: PAGE_SIZE });
    if (res.code !== 0) {
      items.value = [];
      errorCode.value = res.code;
      errorMessage.value = ResolveAiErrorText("载入会话列表失败，请稍后重试", res.code);
      return;
    }
    const page = res.data as AiConversationPage;
    items.value = page?.list ?? [];
    applyCursor(page);
    loaded.value = true;
  } catch (e) {
    console.error("load ai conversation list failed:", e);
    items.value = [];
    errorCode.value = 0;
    errorMessage.value = "载入会话列表失败，请稍后重试";
  } finally {
    loading.value = false;
  }
}

/** 加载更多：带上后端回传的 cursor_time + cursor_id，追加下一页 */
async function loadMore() {
  if (loadingMore.value || loading.value || !hasMore.value || !cursorTime) {
    return;
  }
  loadingMore.value = true;
  try {
    const res = await GetAiConversationList({
      cursor_time: cursorTime,
      cursor_id: cursorId,
      limit: PAGE_SIZE,
    });
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    const page = res.data as AiConversationPage;
    // 游标分页的边界（同一 modify_time 的多条会话、期间有新会话写入）可能返回重复行，按 id 去重
    const exists = new Set(items.value.map((item) => item.id));
    (page?.list ?? []).forEach((item) => {
      if (!exists.has(item.id)) {
        exists.add(item.id);
        items.value.push(item);
      }
    });
    applyCursor(page);
  } catch (e) {
    console.error("load more ai conversation failed:", e);
    ShowTextTipsWarn(globalProperties, "加载更多失败，请稍后重试");
  } finally {
    loadingMore.value = false;
  }
}

// ── 重命名 ──

const renameVisible = ref(false);
const renameTitle = ref("");
const renaming = ref(false);
let renameTargetId = 0;

function handleOpenRename(item: AiConversationItem) {
  renameTargetId = item.id;
  renameTitle.value = item.title ?? "";
  renameVisible.value = true;
}

async function handleSubmitRename() {
  const title = renameTitle.value.trim();
  if (!title) {
    ShowTextTipsWarn(globalProperties, "标题不能为空");
    return;
  }
  renaming.value = true;
  try {
    const res = await PostAiConversationRename(renameTargetId, title);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    // 就地更新：重命名不改 modify_time，列表顺序不变，无需整页重载
    const target = items.value.find((item) => item.id === renameTargetId);
    if (target) {
      target.title = title;
    }
    const current = store.conversations.find((item) => item.id === renameTargetId);
    if (current) {
      current.title = title;
    }
    renameVisible.value = false;
    ShowTextTipsSuccess(globalProperties, "已重命名");
  } catch (e) {
    console.error("rename ai conversation failed:", e);
    ShowTextTipsWarn(globalProperties, "重命名失败，请稍后重试");
  } finally {
    renaming.value = false;
  }
}

// ── 删除（二次确认）──

const deleteVisible = ref(false);
const deleting = ref(false);
const deleteTarget = ref<AiConversationItem | null>(null);

function handleOpenDelete(item: AiConversationItem) {
  deleteTarget.value = item;
  deleteVisible.value = true;
}

async function handleSubmitDelete() {
  const target = deleteTarget.value;
  if (!target) {
    return;
  }
  deleting.value = true;
  try {
    const res = await PostAiConversationDelete(target.id);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    items.value = items.value.filter((item) => item.id !== target.id);
    store.conversations = store.conversations.filter((item) => item.id !== target.id);
    // 删掉的正是浮窗里载入的会话：重置浮窗，避免继续追问一个已不存在的会话
    if (store.conversationId === target.id) {
      store.reset();
      store.close();
    }
    deleteVisible.value = false;
    ShowTextTipsSuccess(globalProperties, "已删除会话");
  } catch (e) {
    console.error("delete ai conversation failed:", e);
    ShowTextTipsWarn(globalProperties, "删除失败，请稍后重试");
  } finally {
    deleting.value = false;
  }
}

// ── 桌面端表格 ──

const listColumns = computed<TableColumn[]>(() => {
  // 显式读一次 sceneList：/ai/scene 晚于首屏返回时列定义要跟着重算，
  // 否则 t-table 的 cell 渲染函数不会重跑，场景标签会一直停在场景 key 上
  //（cell 是闭包，computed 只记录求值期间读到的响应式数据）。
  const sceneList = store.sceneList;
  return [
    {
      title: "标题",
      colKey: "title",
      cell: (_h: unknown, data: CellParams<TableRowData>) => {
        const item = data.row as unknown as AiConversationItem;
        return (
          <t-link theme="primary" onClick={() => handleOpenDetail(item.id)}>
            {GetConversationTitle(item)}
          </t-link>
        );
      },
    },
    {
      title: "场景",
      colKey: "scene",
      width: 120,
      cell: (_h: unknown, data: CellParams<TableRowData>) => {
        const item = data.row as unknown as AiConversationItem;
        return <t-tag variant="light">{GetConversationSceneTitle(sceneList, item.scene)}</t-tag>;
      },
    },
    {
      title: "关联对象",
      colKey: "ref",
      width: 130,
      cell: (_h: unknown, data: CellParams<TableRowData>) => {
        const item = data.row as unknown as AiConversationItem;
        const label = GetConversationRefLabel(item);
        if (!label) {
          return <span class="ai-conv-muted">—</span>;
        }
        if (!CanOpenConversationRef(item)) {
          // 题目引用拿不到 key 时为纯文本：不能用内部 id 拼 /problem/{id}（后端按 key 查询）
          const hint = GetConversationRefHint(item);
          return (
            <span class="ai-conv-ref-plain" title={hint || undefined}>
              {label}
              {hint ? <span class="ai-conv-muted">（暂不可跳转）</span> : null}
            </span>
          );
        }
        return (
          <t-link theme="default" onClick={() => OpenConversationRef(item)}>
            {label}
          </t-link>
        );
      },
    },
    {
      title: "消息数",
      colKey: "message_count",
      width: 90,
      align: "right",
      cell: (_h: unknown, data: CellParams<TableRowData>) => {
        const item = data.row as unknown as AiConversationItem;
        return <span>{item.message_count}</span>;
      },
    },
    {
      title: "累计 Token",
      colKey: "total_tokens",
      width: 120,
      align: "right",
      cell: (_h: unknown, data: CellParams<TableRowData>) => {
        const item = data.row as unknown as AiConversationItem;
        return <span>{item.total_tokens}</span>;
      },
    },
    {
      title: "更新时间",
      colKey: "modify_time",
      width: 130,
      cell: (_h: unknown, data: CellParams<TableRowData>) => {
        const item = data.row as unknown as AiConversationItem;
        return <span class="ai-conv-muted">{GetConversationTimeText(item)}</span>;
      },
    },
    {
      title: "操作",
      colKey: "operation",
      width: 210,
      cell: (_h: unknown, data: CellParams<TableRowData>) => {
        const item = data.row as unknown as AiConversationItem;
        return (
          <t-space size="small">
            <t-button size="small" theme="primary" variant="text" onClick={() => handleContinue(item)}>
              继续对话
            </t-button>
            <t-button size="small" variant="text" onClick={() => handleOpenRename(item)}>
              重命名
            </t-button>
            <t-button size="small" theme="danger" variant="text" onClick={() => handleOpenDelete(item)}>
              删除
            </t-button>
          </t-space>
        );
      },
    },
  ];
});

onMounted(() => {
  // 场景元信息与会话列表并行加载：场景名由 /ai/scene 提供（与浮窗共用 store 的缓存），
  // 晚到时 listColumns 会重算，场景标签自动从 key 变为中文名
  void store.refreshSceneMeta();
  void loadFirstPage();
});
</script>

<template>
  <t-card class="ai-conv-card-page" title="我的对话">
    <template #actions>
      <t-button variant="text" :loading="loading" @click="loadFirstPage">
        <template #icon><t-icon name="refresh" /></template>
        刷新
      </t-button>
    </template>

    <!-- 错误态：错误码经 GetText 出中文；原始码一并显示，便于报障时定位 -->
    <div v-if="errorMessage" class="ai-conv-error">
      <t-alert theme="error" :message="errorMessage" />
      <div class="ai-conv-error-footer">
        <span v-if="errorCode > 0" class="ai-conv-muted">错误码 {{ errorCode }}</span>
        <t-button theme="primary" variant="outline" @click="loadFirstPage">重试</t-button>
      </div>
    </div>

    <template v-else>
      <!-- 加载态（首屏） -->
      <t-loading :loading="loading" size="small" show-overlay text="加载中...">
        <!-- 空态 -->
        <t-empty v-if="loaded && items.length === 0" description="还没有会话，去右下角的 AI 教练聊一句吧" />

        <!-- 桌面端：表格 -->
        <t-table v-else-if="!isMobile" :data="items" :columns="listColumns" row-key="id" :hover="true" table-layout="auto" vertical-align="middle" />

        <!-- 移动端：原生 div 卡片（tdesign 无 Cell 组件） -->
        <div v-else class="ai-conv-cards">
          <div v-for="item in items" :key="item.id" class="ai-conv-item">
            <div class="ai-conv-item-title" @click="handleOpenDetail(item.id)">{{ GetConversationTitle(item) }}</div>
            <div class="ai-conv-item-tags">
              <t-tag size="small" variant="light">{{ GetConversationSceneTitle(store.sceneList, item.scene) }}</t-tag>
              <span
                v-if="GetConversationRefLabel(item)"
                class="ai-conv-item-ref"
                :class="{ 'is-link': CanOpenConversationRef(item) }"
                :title="GetConversationRefHint(item)"
                @click="OpenConversationRef(item)"
              >
                {{ GetConversationRefLabel(item) }}
              </span>
            </div>
            <!-- 不可跳转时的说明（题目引用拿不到 key）：纯文本展示，不生成后端不认的链接 -->
            <div v-if="GetConversationRefHint(item)" class="ai-conv-item-ref-hint">{{ GetConversationRefHint(item) }}</div>
            <div class="ai-conv-item-meta">
              <span>{{ item.message_count }} 条消息</span>
              <span>{{ item.total_tokens }} tokens</span>
              <span>{{ GetConversationTimeText(item) }}</span>
            </div>
            <div class="ai-conv-item-actions">
              <t-button size="small" theme="primary" variant="text" @click="handleContinue(item)">继续对话</t-button>
              <t-button size="small" variant="text" @click="handleOpenRename(item)">重命名</t-button>
              <t-button size="small" theme="danger" variant="text" @click="handleOpenDelete(item)">删除</t-button>
            </div>
          </div>
        </div>
      </t-loading>

      <!-- 加载更多：按后端游标逐页追加，不做全量拉取 -->
      <div v-if="items.length > 0" class="ai-conv-more">
        <t-button v-if="hasMore" theme="default" variant="outline" :loading="loadingMore" @click="loadMore"> 加载更多 </t-button>
        <span v-else class="ai-conv-muted">已显示全部会话</span>
      </div>
    </template>

    <!-- 重命名 -->
    <t-dialog
      v-model:visible="renameVisible"
      header="重命名会话"
      :width="isMobile ? '90%' : '420px'"
      :confirm-btn="{ content: '保存', loading: renaming }"
      @confirm="handleSubmitRename"
    >
      <t-input v-model="renameTitle" :maxlength="120" clearable placeholder="请输入会话标题" @enter="handleSubmitRename" />
    </t-dialog>

    <!-- 删除二次确认 -->
    <t-dialog
      v-model:visible="deleteVisible"
      header="删除会话"
      :width="isMobile ? '90%' : '420px'"
      :confirm-btn="{ content: '删除', theme: 'danger', loading: deleting }"
      @confirm="handleSubmitDelete"
    >
      <p>确定要删除会话「{{ deleteTarget ? GetConversationTitle(deleteTarget) : "" }}」吗？</p>
      <p class="ai-conv-muted">删除后该会话的全部消息都会一并移除，且无法恢复。</p>
    </t-dialog>
  </t-card>
</template>

